// Daily reconcile: Airtable ledger vs QuickBooks purchases.
// AI Bookkeeper purchases carry the Airtable record id as DocNumber (Ref No.),
// so that is the join key. QB Purchase ID on the row is the second key.
const cfg = $('Config').first().json;
const today = $now.toFormat('yyyy-MM-dd');
const purchases = $('Load QB Purchases').first().json.QueryResponse?.Purchase ?? [];
const rows = $('Get All Rows').all()
  .map(i => i.json)
  .filter(j => j && j.id)
  .map(j => ({ id: j.id, f: j.fields ?? j }));

const REC = /^rec[A-Za-z0-9]{14}$/;
const cents = v => Math.round(Number(v || 0) * 100);
const money = v => (cents(v) < 0 ? '-
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const countBy = (list, key) => list.reduce((m, x) => { const k = key(x); if (k) m.set(k, (m.get(k) || 0) + 1); return m; }, new Map());

const ours = purchases.filter(p => REC.test(p.DocNumber || ''));
const others = purchases.filter(p => !REC.test(p.DocNumber || '') && p.AccountRef?.name === cfg.paymentAccount);
const byId = new Map(purchases.map(p => [String(p.Id), p]));
const byDoc = new Map();
for (const p of ours) byDoc.set(p.DocNumber, [...(byDoc.get(p.DocNumber) ?? []), p]);

const emailCounts = countBy(rows, r => String(r.f['Email ID'] || '').trim());
const qbIdCounts = countBy(rows, r => String(r.f['QB Purchase ID'] || '').trim());
const rowIds = new Set(rows.map(r => r.id));

const updates = [];
const issues = [];
let checked = 0, ok = 0, airtableTotal = 0;

for (const r of rows) {
  const f = r.f;
  const qbId = String(f['QB Purchase ID'] || '').trim();
  const posted = f.Status === 'Posted' || qbId !== '' || byDoc.has(r.id);
  if (!posted) continue; // Needs review / Approved rows are not in QuickBooks yet
  checked++;
  airtableTotal += cents(f.Amount);

  const found = [];
  if (!qbId) {
    const inQb = byDoc.get(r.id);
    found.push(inQb
      ? `In QuickBooks (ID ${inQb.map(p => p.Id).join(', ')}) but Airtable has no QB Purchase ID: the Post workflow will post it again`
      : 'Status Posted but no QB Purchase ID');
  } else {
    const p = byId.get(qbId);
    if (!p) {
      found.push(`Missing in QuickBooks: purchase ${qbId} not found (deleted?)`);
    } else {
      if (cents(p.TotalAmt) !== cents(f.Amount)) found.push(`Amount mismatch: Airtable ${money(f.Amount)} vs QuickBooks ${money(p.TotalAmt)}`);
      const d = String(f.Date || '').slice(0, 10);
      if (p.TxnDate !== d) found.push(`Date mismatch: Airtable ${d || 'empty'} vs QuickBooks ${p.TxnDate}`);
      if (p.DocNumber !== r.id) found.push(`QuickBooks purchase ${qbId} has Ref No. ${p.DocNumber || 'none'}, not this row`);
    }
  }
  const dupes = byDoc.get(r.id) ?? [];
  if (dupes.length > 1) found.push(`Duplicate in QuickBooks: ${dupes.length} purchases with Ref No. ${r.id} (IDs ${dupes.map(p => p.Id).join(', ')})`);
  const emailId = String(f['Email ID'] || '').trim();
  if (emailId && emailCounts.get(emailId) > 1) found.push('Duplicate in Airtable: same Email ID on another row');
  if (qbId && qbIdCounts.get(qbId) > 1) found.push('Duplicate in Airtable: same QB Purchase ID on another row');

  if (found.length === 0) ok++;
  for (const msg of found) issues.push({ where: `${f.Vendor || '?'} ${money(f.Amount)} (${r.id})`, msg });
  updates.push({ id: r.id, 'Recon Check': found.length ? `FLAG ${today}: ${found.join('; ')}` : `OK ${today}` });
}

// AI Bookkeeper purchases in QuickBooks with no Airtable row at all.
for (const p of ours) {
  if (!rowIds.has(p.DocNumber)) issues.push({ where: `QuickBooks purchase ${p.Id}, ${p.EntityRef?.name || '?'} ${money(p.TotalAmt)}`, msg: `No Airtable row for Ref No. ${p.DocNumber}` });
}

const qbTotal = ours.reduce((s, p) => s + cents(p.TotalAmt), 0);
const diff = airtableTotal - qbTotal;
const otherTotal = others.reduce((s, p) => s + cents(p.TotalAmt), 0);

const summary = [
  ['Airtable rows checked', checked],
  ['Matched OK', ok],
  ['Issues', issues.length],
  ['Airtable posted total', money(airtableTotal / 100)],
  ['QuickBooks AI Bookkeeper total', money(qbTotal / 100)],
  ['Difference', money(diff / 100)],
  [`Other ${cfg.paymentAccount} charges (not from AI Bookkeeper, not checked)`, `${others.length}, ${money(otherTotal / 100)}`],
];

const html = `<h2>AI Bookkeeper reconcile, ${esc(today)}</h2>
<table cellpadding="6" style="border-collapse:collapse">${summary.map(([k, v]) => `<tr><td>${esc(k)}</td><td><b>${esc(v)}</b></td></tr>`).join('')}</table>
${issues.length
  ? `<h3>Issues</h3><table border="1" cellpadding="6" style="border-collapse:collapse"><tr><th>Transaction</th><th>Issue</th></tr>${issues.map(i => `<tr><td>${esc(i.where)}</td><td>${esc(i.msg)}</td></tr>`).join('')}</table>`
  : '<p>Everything matches.</p>'}`;

return [{ json: { date: today, checked, ok, issueCount: issues.length, issues, diff: diff / 100, updates, html } }];
